head.b:skin:
/* <Variable name="page.background" description="Page background" type="color" default="#f0f0e8" value="#f0f0e8"/><Variable name="page.text" description="Text color" type="color" default="#151812" value="#151812"/><Variable name="theme.accent" description="Accent color" type="color" default="#bbff32" value="#bbff32"/> */
/* Blogger stylesheet compatibility: restore the spacing Blogger's own widget stylesheet removes, and keep post content inside a phone screen. */
h1{margin:.67em 0}h2{margin:.83em 0}h3{margin:1em 0}h4{margin:1.33em 0}h1,h2,h3,h4,a img{position:static}body{padding:0;word-break:normal}.post-body{width:auto;overflow-x:auto}.post-body a[style*='margin-left'],.post-body a[style*='margin-right']{margin-inline:0!important}.post-body .separator,.post-body .tr-caption-container{max-width:100%}.widget .post-body ul,.widget .post-body ol{margin:1em 0;padding:0 0 0 1.4em;line-height:inherit}.widget .post-body li{margin:0 0 .35em;padding:0}.latest-empty{display:none}.single-view{font-size:1rem}.single-view .post-title{overflow-wrap:anywhere}
:root{--bg:$(page.background);--ink:$(page.text);--accent:$(theme.accent);--heading:"Barlow Condensed",Impact,sans-serif;--body:"Barlow",sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 var(--body)}h1,h2,h3{font-family:var(--heading);line-height:1.15}a{color:inherit;text-underline-offset:4px}a:hover{text-decoration-thickness:2px}img{max-width:100%;height:auto}svg{max-width:100%;height:auto}button,input{font:inherit}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid currentColor;outline-offset:5px}a,button,summary{touch-action:manipulation}nav{max-width:100%}p,h1,h2,h3,a{overflow-wrap:anywhere}.skip-link{position:fixed;top:-100px;left:16px;z-index:100;background:var(--ink);color:var(--bg);padding:12px}.skip-link:focus{top:12px}.section,.widget{min-width:0;margin:0;padding:0;line-height:inherit}.latest{max-width:1200px;margin:64px auto;padding:0 24px}.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.post-card{min-width:0}.post-title a{text-decoration:none}.post-title a:hover{text-decoration:underline}.post-media{display:block;aspect-ratio:16/10;overflow:hidden;background:color-mix(in srgb,var(--accent) 12%,var(--bg))}.post-media img{width:100%;height:100%;object-fit:cover}.post-art{height:100%;display:grid;place-items:center;font:italic 70px var(--heading);color:var(--accent)}.post-meta{margin-top:18px;font-size:12px}.post-meta a{margin-right:12px}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:40px;padding-top:20px;border-top:1px solid currentColor}.pager a{padding:10px 0}.post-body{max-width:70ch;margin-inline:auto;overflow-wrap:anywhere}.post-body img,.post-body iframe{max-width:100%}.post-body pre,.post-body table{display:block;overflow:auto;max-width:100%}.single-view .latest{max-width:900px}.single-view .section-heading{display:none}.single-view .post-title{font-size:clamp(32px,5vw,62px)}.single-view #comments{margin-top:60px}.empty-state,.error-state{padding:45px 0}.error-state{max-width:900px;margin:auto;padding:70px 24px}.listing-heading{font-size:clamp(28px,5vw,52px)}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.posts-grid{grid-template-columns:1fr}.latest{margin:45px auto}.pager{flex-wrap:wrap}}
html{scroll-behavior:smooth}body{margin:0}a{color:inherit}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid var(--accent);outline-offset:5px}img{max-width:100%}header,footer{position:relative}nav{display:flex;gap:24px;flex-wrap:wrap}nav a{text-decoration:none}.wordmark{text-decoration:none;font-weight:700}.brandline{display:flex;align-items:center;justify-content:space-between;gap:24px}.eyebrow{font-size:12px;letter-spacing:.16em;text-transform:uppercase}.art{display:block;width:100%;height:auto}p{line-height:1.7}.post-title a{text-decoration:none}.post-meta{font-size:11px;letter-spacing:.07em;text-transform:uppercase}.post-excerpt{line-height:1.6}.post-media{display:block;width:100%;aspect-ratio:16/10;object-fit:cover}.section-heading{font-size:30px;margin:0 0 30px}.post-title{font-size:24px;line-height:1.2}.post-card{min-width:0}footer{margin-top:80px}footer p{margin:0}.footerline{display:flex;justify-content:space-between;gap:25px;align-items:center}.page-content,.post-body{max-width:760px;margin:auto}.post-body{line-height:1.8}main>.section-heading,main>.posts-grid{max-width:1200px;margin-left:auto;margin-right:auto}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.brandline,.footerline{align-items:flex-start;flex-direction:column}nav{gap:16px}.section-heading{font-size:26px}.post-title{font-size:22px}main>.section-heading,main>.posts-grid{margin-left:20px;margin-right:20px}}body{font-family:"Barlow",sans-serif;color:#151812;background:#f0f0e8}header{padding:22px 4vw;border-bottom:2px solid #151812}.wordmark{font:800 italic 35px "Barlow Condensed",sans-serif;letter-spacing:-.04em}.wordmark span{font-size:13px;vertical-align:top;margin:4px}nav{font-size:12px;text-transform:uppercase;font-weight:600}.ride-hero{background:#151812;color:#f0f0e8;padding:25px 4vw 30px;position:relative;overflow:hidden}.ride-hero-top{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #4b5145;padding-bottom:14px;font-size:10px;letter-spacing:.13em}.ride-hero-top .eyebrow{font-size:10px}.ride-hero h1{font:800 clamp(94px,14vw,196px)/.79 "Barlow Condensed",sans-serif;letter-spacing:-.045em;margin:48px 0;position:relative;z-index:2;max-width:670px}.ride-hero h1 em{color:#bbff32;font-weight:700}.ride-art{position:absolute;width:49%;right:0;top:22%;transform:rotate(-4deg)}.ride-hero-bottom{position:relative;z-index:3;display:flex;justify-content:space-between;align-items:end;gap:30px}.ride-hero-bottom p{font-size:13px;color:#c3c8ba;max-width:370px}.ride-hero-bottom a{display:flex;justify-content:space-between;gap:70px;background:#bbff32;color:#151812;padding:18px 22px;font-size:12px;font-weight:700;text-decoration:none}.ride-hero-bottom a span{transition:transform .2s}.ride-hero-bottom a:hover span{transform:translate(4px,-4px)}.ride-types{padding:60px 4vw;display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:20px}.ride-types h2{font:700 40px/.95 "Barlow Condensed",sans-serif;letter-spacing:-.025em}.eyebrow{font-size:10px;font-weight:600}.ride-types>a{padding:22px 18px;min-height:180px;text-decoration:none;border:2px solid #151812;display:flex;flex-direction:column;position:relative;transition:background .2s}.ride-types>a:hover{background:#bbff32}.ride-types>a span{font-size:9px;font-weight:600;letter-spacing:.05em}.ride-types strong{font:700 36px/.92 "Barlow Condensed",sans-serif;margin-top:35px}.ride-types i{position:absolute;right:15px;bottom:13px;font-size:25px;font-style:normal}.ride-strip{padding:16px 4vw;background:#bbff32;display:flex;justify-content:space-between;font:700 italic 29px "Barlow Condensed",sans-serif}.ride-label{margin:60px 4vw 12px}.section-heading{font:800 54px/.95 "Barlow Condensed",sans-serif;margin:0 4vw 30px;letter-spacing:-.03em}.posts-grid{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:25px;margin:0 4vw}.post-media{aspect-ratio:5/4;background:#d6dcc9;filter:grayscale(1)}.post-card:first-child .post-media{aspect-ratio:16/9}.post-meta{font-size:10px;font-weight:600;margin-top:16px}.post-title{font:700 35px/.98 "Barlow Condensed",sans-serif;text-transform:uppercase;margin:15px 0}.post-excerpt{font-size:13px;color:#535b49}.kit-section{display:grid;grid-template-columns:.55fr 1.4fr;gap:60px;margin:80px 4vw 0;padding:45px;background:#e0e4d6;border:2px solid #151812}.kit-number{font:800 98px/.97 "Barlow Condensed",sans-serif;color:#566246;border-right:2px solid #151812}.kit-section h2{font:800 52px/.95 "Barlow Condensed",sans-serif;letter-spacing:-.03em;margin:20px 0}.kit-lines p{padding:13px 0;border-bottom:1px solid #a3ad96;display:flex;justify-content:space-between;gap:30px;font-size:11px;margin:0}.kit-lines p span{color:#535b49}.kit-section>a,.kit-section div>a{display:inline-block;margin-top:25px;font-size:12px;font-weight:bold}footer{padding:30px 4vw;background:#151812;color:#f0f0e8;font-size:10px}.footerline strong{font:800 italic 40px "Barlow Condensed",sans-serif}@media(max-width:700px){.ride-hero h1{font-size:105px;margin-bottom:15px}.ride-art{position:relative;width:100%;top:auto;right:auto;margin-top:-10px}.ride-hero-bottom{align-items:start;flex-direction:column}.ride-hero-top>span{display:none}.ride-types{grid-template-columns:1fr 1fr}.ride-types>div{grid-column:span 2}.ride-types>a:last-child{grid-column:span 2;min-height:120px}.ride-strip{font-size:18px}.posts-grid{grid-template-columns:1fr}.kit-section{grid-template-columns:1fr;padding:25px;gap:20px}.kit-number{display:none}.kit-section h2{font-size:40px}.kit-lines p{flex-direction:column;gap:5px}.section-heading{font-size:43px}}
.latest{max-width:none;margin:55px 0;padding:0}.latest>.section-heading,.latest>.posts-grid{max-width:none}a:hover span,a:focus-visible span{transition:transform .2s}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{animation:none!important;transition:none!important}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}*,*::before,*::after{animation:none!important;transition:none!important}.post-media img{transform:none!important}}@media print{nav,.skip-link,.pager{display:none!important}body{background:white;color:black}}
